async function loadShopifyQaFixture(){
  if(!QA_MODE||typeof state==="undefined"||!Array.isArray(state.clients))return;
  try{
    const r=await fetch("qa-shopify-fixture.json?v=20260920-live1",{cache:"no-store"});
    if(!r.ok)throw new Error("HTTP "+r.status);
    qaFixture=await r.json();
    window.B2B_QA_DATA=qaFixture;
    const base=920000, customers=qaFixture.b2bCustomerSample||[], orders=qaFixture.recentOrders||[];
    const existing=new Set(state.clients.map(c=>String(c.id)));
    customers.forEach((q,i)=>{
      const id=base+i;if(existing.has(String(id)))return;
      const assigned=orders.filter((_,j)=>j%Math.max(1,customers.length)===i).slice(0,Math.max(1,Math.min(5,q.ordersCount||1)));
      const fallback=orders[i%Math.max(1,orders.length)];
      const hist=(assigned.length?assigned:(fallback?[fallback]:[])).map(o=>({date:String(o.date||"").slice(0,10),amount:+o.total||0,total:+o.total||0}));
      const last=hist[0]?.date||qaDate(-(7+i%70));
      state.clients.push({
        id,cliente:q.customer||("Cliente B2B "+(i+1)),contacto:q.customer||("Cliente B2B "+(i+1)),
        email:"qa.b2b"+(i+1)+"@example.test",ultimaB2B:last,ultima:last,
        reorderMedian:[30,45,60,75][i%4],reorderDays:[30,45,60,75][i%4],
        b2bConfirmedOrders:+q.ordersCount||2,pedidos:+q.ordersCount||2,
        totalSpent:+q.totalSpent||0,ordersHistory:hist,qaShopify:true
      });
    });
    const cats=qaFixture.catalogSample||[];
    incoming=(cats.slice(0,8).flatMap((p,i)=>(p.variants||[]).slice(0,1).map(v=>({
      sku:v.sku||("QA-SKU-"+i),product:p.title||"Producto Shopify",qty:24+(i*12),eta:qaDate(4+i*2)
    })))).filter(x=>x.sku);
    waiting=[];nextActions=[];pipeline={};
    customers.slice(0,20).forEach((q,i)=>{
      const id=base+i;
      pipeline[id]={stage:STAGES[i%STAGES.length],amount:i%6===5?Math.round((+q.totalSpent||0)/Math.max(1,+q.ordersCount||1)):0,updatedAt:new Date().toISOString()};
      nextActions.push({id:"qa-shopify-action-"+i,clientId:id,type:["Seguimiento","Cotización","Recompra","Llamada"][i%4],date:qaDate((i%5)-2),note:"QA con métricas anonimizadas de Shopify.",done:false,createdAt:new Date().toISOString()});
      if(i<Math.min(6,incoming.length)){waiting.push({clientId:id,sku:incoming[i].sku,product:incoming[i].product,note:"QA: cliente en espera",active:true,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})}
    });
    localStorage.setItem(KEY,JSON.stringify(incoming));
    localStorage.setItem(WAIT_KEY,JSON.stringify(waiting));
    localStorage.setItem(TASK_KEY,JSON.stringify(nextActions));
    localStorage.setItem(PIPE_KEY,JSON.stringify(pipeline));
    document.documentElement.dataset.qaMode="shopify";
    const old=document.querySelector(".qaModeBadge");if(old)old.remove();
    const badge=document.createElement("div");badge.className="qaModeBadge";badge.textContent="MODO QA · SHOPIFY REAL ANONIMIZADO";document.body.appendChild(badge);
  }catch(e){
    console.error("QA Shopify fixture:",e);
    const badge=document.createElement("div");badge.className="qaModeBadge";badge.textContent="QA · ERROR CARGANDO SHOPIFY";document.body.appendChild(badge);
  }
}
function excelDate(v){if(!v)return"";if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);if(typeof v==="number"){const d=new Date(Math.round((v-25569)*86400000));return isNaN(d)?"":d.toISOString().slice(0,10)}const d=new Date(v);return isNaN(d)?String(v).slice(0,10):d.toISOString().slice(0,10)}
