async function accessHash(v){const buf=await crypto.subtle.digest("SHA-256",new TextEncoder().encode("YEPPO-V10|"+String(v)));return [...new Uint8Array(buf)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function setLocalAccess(code){localStorage.setItem(ACCESS_KEY,await accessHash(code))}
async function verifyLocalAccess(code){const h=localStorage.getItem(ACCESS_KEY);return !h||h===await accessHash(code)}
