function salesRows(){const out=[];const cs=state?.clients||[];for(const c of cs){const pools=[c.ordersHistory,c.orderHistory,c.pedidosHistorial,c.purchases,c.compras,c.orders];for(const p of pools){if(!Array.isArray(p))continue;for(const o of p){const date=o.date||o.fecha||o.createdAt||o.created_at||o.orderDate,amount=+(o.amount||o.total||o.venta||o.sales||o.monto||0);if(date&&amount)out.push({date:String(date).slice(0,10),amount})}}}return out}
function masterSales(){if(liveShopify?.sales7?.length){const src=liveShopify.sales7.slice(-7),days=src.map(x=>{const d=new Date(x.date+"T12:00:00");return{key:x.date,label:d.toLocaleDateString("es-CL",{weekday:"short"}).replace(".",""),value:+x.sales||+x.totalSales||0}}),todayValue=days[days.length-1]?.value||0,week=days.reduce((a,x)=>a+x.value,0),max=Math.max(...days.map(x=>x.value),1);return{todayValue,week,days,max,hasData:true}}if(QA_MODE&&qaFixture?.dashboard?.salesLast7Days?.length){const src=qaFixture.dashboard.salesLast7Days.slice(-7),days=src.map(x=>{const d=new Date(x.date+"T12:00:00");return{key:x.date,label:d.toLocaleDateString("es-CL",{weekday:"short"}).replace(".",""),value:+x.totalSales||0}}),todayValue=+qaFixture.dashboard.today?.totalSales||days[days.length-1]?.value||0,week=days.reduce((a,x)=>a+x.value,0),max=Math.max(...days.map(x=>x.value),1);return{todayValue,week,days,max,hasData:true}}const rows=salesRows(),today=new Date(),iso=d=>d.toISOString().slice(0,10),days=[];for(let i=6;i>=0;i--){const d=new Date(today);d.setDate(d.getDate()-i);const key=iso(d),value=rows.filter(x=>x.date===key).reduce((a,x)=>a+x.amount,0);days.push({key,label:d.toLocaleDateString("es-CL",{weekday:"short"}).replace(".",""),value})}const todayValue=days[6].value,week=days.reduce((a,x)=>a+x.value,0),max=Math.max(...days.map(x=>x.value),1);return{todayValue,week,days,max,hasData:rows.length>0}}
